import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')['rgb']
def largest(mask):
    lab,n = ndimage.label(mask)
    if n==0: return None
    sizes = ndimage.sum(mask, lab, range(1,n+1))
    return lab==(1+int(np.argmax(sizes)))
def blockmask(f):
    R,G,B = f[...,0].astype(int), f[...,1].astype(int), f[...,2].astype(int)
    return (R<118)&(G<78)&(B<58)&(R-G>18)&(R>45)
def ballmask(f):
    R,G,B = f[...,0].astype(int), f[...,1].astype(int), f[...,2].astype(int)
    return (R>150)&(R-G>55)&(G-B>20)&(B<90)
for i in range(0,96,4):
    f=d[i]
    mk=largest(blockmask(f)); yk,xk=np.where(mk)
    mb=largest(ballmask(f)); yb,xb=np.where(mb)
    print(i,'block cx %.1f x[%d,%d] y[%d,%d] n=%d | ball cx %.1f cy %.1f'%(
      xk.mean(),xk.min(),xk.max(),yk.min(),yk.max(),len(xk), xb.mean(),yb.mean()))
\""
